// This file is generated by AI.

// 参考音频选择对话框 (从角色的参考音频里挑一条)。
//
// 它只做两件事: **选一条**、以及**补齐语料** (「添加参考音频」)。
// 列表、搜索、添加流程都由 `ReferenceListEditor` 提供 —— 与「编辑角色」对话框里的是
// 同一个组件, 因此两处的搜索框、添加按钮、列表滚动行为完全一致。
//
// 刻意不放在这里的东西:
// * **导出角色**: 那是角色级操作, 属于「编辑角色」与「选择角色」的职责, 与"挑一条参考
//   音频"无关;
// * **在底部填参考文本**: 参考文本是"添加时"的信息, 归添加对话框管; 摆在这里既会被
//   误认为"修改当前选中项的文本", 也让人不清楚它什么时候生效。

import { Button } from '@fluentui/react-components';

import type { Character } from '../commands/voice';
import { AppDialog } from '../components/AppDialog';
import { ReferenceListEditor } from './ReferenceListEditor';

interface Props {
  open: boolean;
  character: Character | null;
  selectedHash: string | null;
  /** 选中某一条参考音频 (调用方通常会随之关闭本对话框) */
  onPick: (hash: string) => void;
  /** 新增了一条参考音频: 把它设为当前项, 但对话框**保持打开** */
  onAdded: (hash: string) => void;
  onClose: () => void;
  onCharactersChanged: () => void;
}

export function VoiceReferenceDialog({
  open,
  character,
  selectedHash,
  onPick,
  onAdded,
  onClose,
  onCharactersChanged,
}: Props) {
  // 没有角色时不存在"选参考音频"这件事。调用方本来就不该打开它, 这里再兜一层,
  // 避免出现一个空壳对话框。
  if (!open || !character) return null;

  return (
    <AppDialog
      title={`参考音频 · ${character.name}`}
      description="参考文本必须与音频逐字一致；时长须在 3~10 秒之间。"
      size="large"
      height={600}
      compact
      onClose={onClose}
      footer={
        <Button appearance="secondary" onClick={onClose}>
          关闭
        </Button>
      }
    >
      <ReferenceListEditor
        character={character}
        selectedHash={selectedHash}
        onPick={onPick}
        onAdded={onAdded}
        onChanged={onCharactersChanged}
      />
    </AppDialog>
  );
}
